<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>The Glorious Age of Media Unity</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link href="https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Source+Serif+4:ital,wght@0,400;0,600;1,400&display=swap" rel="stylesheet">
    <style>
        :root {
            --bg: #f7f4ee;
            --surface: #ffffff;
            --accent: #d13a3a;
            --text-primary: #2c2c2c;
            --text-muted: #6e6e6e;
            --border: #e5e1d9;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Source Serif 4', Georgia, serif;
            background-color: var(--bg);
            color: var(--text-primary);
            line-height: 1.7;
            padding: 2rem;
        }

        .container {
            max-width: 800px;
            margin: 0 auto;
            background: var(--surface);
            padding: 3rem;
            border-radius: 4px;
            box-shadow: 0 4px 20px rgba(0,0,0,0.05);
            position: relative;
            overflow: hidden;
        }

        .container::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 4px;
            background: linear-gradient(90deg, var(--accent), #e89c38);
        }

        header {
            text-align: center;
            margin-bottom: 3rem;
            padding-bottom: 2rem;
            border-bottom: 1px solid var(--border);
        }

        h1 {
            font-family: 'Bebas Neue', sans-serif;
            font-size: 3.2rem;
            letter-spacing: 0.08em;
            color: var(--accent);
            margin-bottom: 0.5rem;
            text-transform: uppercase;
        }

        .subtitle {
            font-style: italic;
            color: var(--text-muted);
            font-size: 1.2rem;
        }

        .date {
            font-family: 'DM Mono', monospace;
            font-size: 0.85rem;
            color: var(--text-muted);
            margin-top: 1rem;
            letter-spacing: 0.05em;
        }

        h2 {
            font-family: 'Bebas Neue', sans-serif;
            font-size: 2rem;
            letter-spacing: 0.05em;
            color: var(--text-primary);
            margin: 2.5rem 0 1.2rem;
            padding-left: 1rem;
            border-left: 3px solid var(--accent);
        }

        p {
            margin-bottom: 1.5rem;
            text-align: justify;
        }

        .pullquote {
            font-size: 1.4rem;
            font-style: italic;
            color: var(--accent);
            padding: 1.5rem;
            margin: 2rem 0;
            background: rgba(209, 58, 58, 0.05);
            border-radius: 2px;
            text-align: center;
        }

        .pullquote::before {
            content: '"';
            font-size: 3rem;
            color: var(--accent);
            opacity: 0.3;
            display: block;
            line-height: 1;
            margin-bottom: 0.5rem;
        }

        .satire-box {
            background: rgba(0,0,0,0.02);
            padding: 2rem;
            margin: 2rem 0;
            border-left: 2px solid var(--accent);
            position: relative;
        }

        .satire-box::before {
            content: 'SATIRE MODE: ACTIVATED';
            position: absolute;
            top: -0.8rem;
            left: 1rem;
            background: var(--surface);
            padding: 0 0.5rem;
            font-family: 'DM Mono', monospace;
            font-size: 0.75rem;
            color: var(--accent);
            letter-spacing: 0.05em;
        }

        .alternative-view {
            margin-top: 3rem;
            padding-top: 2rem;
            border-top: 1px dashed var(--border);
        }

